<?php
class HorarioController{function __construct(private Horario $model){} function listar(){return ['success'=>true,'data'=>$this->model->obtenerTodos($_POST['buscar']??'')];} function obtener($id){ $d=$this->model->obtenerPorId($id);return $d?['success'=>true,'data'=>$d]:['success'=>false,'message'=>'Registro no encontrado'];} function guardar($d){try{$this->model->insertar($d);return ['success'=>true,'message'=>'Registro guardado correctamente.'];}catch(PDOException $e){return ['success'=>false,'message'=>'No se pudo guardar el registro.'];}} function actualizar($d){try{$this->model->actualizar($d);return ['success'=>true,'message'=>'Registro actualizado correctamente.'];}catch(PDOException $e){return ['success'=>false,'message'=>'No se pudo actualizar el registro.'];}} function eliminar($id){try{$this->model->eliminar($id);return ['success'=>true,'message'=>'Registro eliminado correctamente.'];}catch(PDOException $e){return ['success'=>false,'message'=>'No se puede eliminar porque tiene registros relacionados.'];}}}